#include <cstdint>
#include <iostream>

// Demonstrates operational growth: Linear O(n) vs Quadratic O(n^2)
int main() {
    int n = 0;
    if (!(std::cin >> n) || n <= 0) {
        return 0;
    }

    std::uint64_t linearComparisons = 0;
    for (int i = 0; i < n; ++i) {
        ++linearComparisons;
    }

    std::uint64_t quadraticComparisons = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            ++quadraticComparisons;
        }
    }

    std::cout << "Input size n: " << n << "\n";
    std::cout << "Linear steps O(n): " << linearComparisons << "\n";
    std::cout << "Pairwise comparisons: " << quadraticComparisons << "\n";
    std::cout << "Formula n*(n-1)/2: " << (static_cast<std::uint64_t>(n) * (n - 1)) / 2 << "\n";

    return 0;
}

#include <array>
#include <iostream>

// Fig. 20.3: display elements from index low through index high with alignment
template <typename T, std::size_t size>
void displayElements(const std::array<T, size>& items, std::size_t low, std::size_t high) {
    for (std::size_t i = 0; i < items.size() && i < low; ++i) {
        std::cout << "   "; // display spaces for alignment
    }

    for (std::size_t i = low; i < items.size() && i <= high; ++i) {
        std::cout << items[i] << " "; // display element
    }

    std::cout << "\n";
}

// Fig. 20.3: perform a binary search on the data
template <typename T, std::size_t size>
int binarySearch(const std::array<T, size>& items, const T& key) {
    if constexpr (size == 0) return -1;
    int low = 0;
    int high = static_cast<int>(items.size()) - 1;
    int middle = (low + high + 1) / 2;
    int location = -1;

    do {
        displayElements(items, static_cast<std::size_t>(low), static_cast<std::size_t>(high));

        for (int i = 0; i < middle; ++i) {
            std::cout << "   ";
        }

        std::cout << " * \n";

        if (key == items[static_cast<std::size_t>(middle)]) {
            location = middle;
        } else if (key < items[static_cast<std::size_t>(middle)]) {
            high = middle - 1;
        } else {
            low = middle + 1;
        }

        middle = (low + high + 1) / 2;
    } while ((low <= high) && (location == -1));

    return location;
}

int main() {
    // Sorted array matching the exact values in Fig. 20.3 sample output
    constexpr std::size_t arraySize = 15;
    std::array<int, arraySize> arrayToSearch{
        10, 23, 27, 48, 52, 55, 58, 60, 62, 63, 68, 72, 75, 92, 97
    };

    // Initial display of all elements
    displayElements(arrayToSearch, 0, arrayToSearch.size() - 1);

    int searchKey = 0;
    std::cout << "\nPlease enter an integer value (-1 to quit): ";
    if (std::cin >> searchKey && searchKey != -1) {
        std::cout << searchKey << "\n\n";
        int position = binarySearch(arrayToSearch, searchKey);

        if (position == -1) {
            std::cout << "The integer " << searchKey << " was not found.\n";
        } else {
            std::cout << "The integer " << searchKey << " was found in position " << position << ".\n";
        }
    }

    return 0;
}
